float theta = std::acos(u.x);
float phi = 2.0f * M_PI * u.y;

float sin_theta = std::sin(theta);
float cos_theta = std::cos(theta);

Vector3f direction;
direction.x = sin_theta * std::cos(phi);
direction.y = sin_theta * std::sin(phi);
direction.z = cos_theta;

return direction;

